async (page) => {
  const assert = (condition, message) => { if (!condition) throw new Error(message) }
  const root = 'E:/AAA2026学习工作/智能教育软件工程实践/code/frontend/output/playwright/'
  const passed = []
  await page.goto('http://127.0.0.1:5173/question-bank?status=confirmed')
  await page.getByRole('heading', { name: '我的题库', exact: true }).waitFor()
  await page.getByText('选择本页', { exact: true }).click()
  await page.getByRole('button', { name: '下一页', exact: true }).click()
  await page.getByText('选择本页', { exact: true }).click()
  await page.getByText('已选 8 题', { exact: true }).waitFor()
  const downloading = page.waitForEvent('download')
  await page.getByRole('button', { name: '批量导出 TXT', exact: true }).click()
  await (await downloading).saveAs(root + 'batch-confirmed-8.txt')
  await page.getByRole('button', { name: '清空选择', exact: true }).click()
  await page.getByText('已选 0 题', { exact: true }).waitFor()
  passed.push('8道定稿跨2页选择、批量TXT下载、清空选择')
  await page.goto('http://127.0.0.1:5173/question-bank?status=pending')
  await page.getByRole('button', { name: '删除', exact: true }).first().click()
  const deleting = page.getByRole('dialog', { name: '删除习题', exact: true })
  await deleting.getByRole('button', { name: '取消', exact: true }).click()
  assert(await page.locator('article').count() === 4, '取消删除改变了题库')
  await page.getByRole('button', { name: '删除', exact: true }).first().click()
  await deleting.getByRole('button', { name: '确认删除', exact: true }).click()
  await page.reload()
  await page.getByRole('heading', { name: '我的题库', exact: true }).waitFor()
  assert(await page.locator('article').count() === 3, '删除未持久保存')
  passed.push('删除取消不变、明确确认删除并刷新持久化')
  await page.goto('http://127.0.0.1:5173/question-bank')
  await page.getByRole('button', { name: '评分 / 评价', exact: true }).first().click()
  const rating = page.getByRole('dialog', { name: '我的评分与评价', exact: true })
  await rating.getByRole('slider').press('ArrowLeft')
  await rating.getByRole('slider').press('ArrowRight')
  await rating.getByRole('textbox').fill('浏览器验收：题目条件完整，适合课堂使用。')
  await rating.getByRole('button', { name: '保存评价', exact: true }).click()
  await page.reload()
  await page.getByText('我的评价：浏览器验收：题目条件完整，适合课堂使用。', { exact: true }).waitFor()
  passed.push('评分键盘操作与评价保存刷新持久化')
  await page.goto('http://127.0.0.1:5173/excellent-questions')
  await page.getByRole('button', { name: '讨论区', exact: true }).first().click()
  const drawer = page.locator('.el-drawer')
  await drawer.getByPlaceholder('分享你的想法、疑问或解题思路...').fill('浏览器验收顶层讨论：这道题适合课前导入。')
  await drawer.getByRole('button', { name: '发送', exact: true }).click()
  await drawer.getByText('浏览器验收顶层讨论：这道题适合课前导入。', { exact: true }).waitFor()
  await drawer.getByRole('button', { name: '回复', exact: true }).first().click()
  await drawer.getByPlaceholder('说点什么...').fill('浏览器验收二级回复：可以追加受力分析。')
  await drawer.getByRole('button', { name: '发送回复', exact: true }).click()
  await drawer.getByText('浏览器验收二级回复：可以追加受力分析。', { exact: true }).waitFor()
  assert((await drawer.locator('.reply-item').innerText()).includes('@teacher'), '@回复对象未展示')
  await page.screenshot({ path: root + 'excellent-question-discussion.png', fullPage: true, animations: 'disabled' })
  await drawer.locator('.reply-item .disc-delete-btn').click()
  await page.getByRole('dialog', { name: '提示', exact: true }).getByRole('button', { name: '删除', exact: true }).click()
  await drawer.getByText('浏览器验收二级回复：可以追加受力分析。', { exact: true }).waitFor({ state: 'hidden' })
  await drawer.locator('.disc-top .disc-delete-btn').click()
  await page.getByRole('dialog', { name: '提示', exact: true }).getByRole('button', { name: '删除', exact: true }).click()
  await drawer.getByText('暂无讨论，快来发表第一条~', { exact: true }).waitFor()
  passed.push('顶层讨论、@二级回复、删除回复、删除顶层闭环')
  return { passed }
}
